  str_aircraft_desc_7101003 = "El Colossus se puede operar desde el Puente. Tiene una gran vista y ofrece un amplio campo visual, y es clave para <color=#00F6FF>desbloquear el acceso a las ventajas</color>, así como elevar el estado de Ánimo dentro del Colossus. Ciertos Aurorians también pueden aumentar el <color=#00F6FF>Estado de Ánimo amueblando</color> en el Colossus.",
  str_aircraft_desc_7101004 = "El Colossus se puede operar desde el Puente. Tiene una gran vista y ofrece un amplio campo visual, y es clave para <color=#00F6FF>desbloquear el acceso a las ventajas</color>, así como elevar el estado de Ánimo dentro del Colossus. Ciertos Aurorians también pueden aumentar el <color=#00F6FF>Estado de Ánimo amueblando</color> en el Colossus.",
  str_aircraft_desc_7101005 = "El Colossus se puede operar desde el Puente. Tiene una gran vista y ofrece un amplio campo visual, y es clave para <color=#00F6FF>desbloquear el acceso a las ventajas</color>, así como elevar el estado de Ánimo dentro del Colossus. Ciertos Aurorians también pueden aumentar el <color=#00F6FF>Estado de Ánimo amueblando</color> en el Colossus.",
  str_aircraft_desc_7102001 = "Red Lumina es la central eléctrica del Colossus, <color=#00F6FF>proveyendo lumina a cada habitación</color>. Es el lugar favorito de las Luciérnagas, así que puedes aumentar tu <color=#00F6FF>velocidad de recuperación de Luciérnaga</color> aquí. Algunos Aurorians son aficionados a luciérnagas y pueden acelerar más la <color=#00F6FF>tasa de recuperación de las luciérnagas</color>.",
