  str_aircraft_desc_7102005 = "Red Lumina es la central eléctrica del Colossus, <color=#00F6FF>proveyendo lumina a cada habitación</color>. Es el lugar favorito de las Luciérnagas, así que puedes aumentar tu <color=#00F6FF>velocidad de recuperación de Luciérnaga</color> aquí. Algunos Aurorians son aficionados a luciérnagas y pueden acelerar más la <color=#00F6FF>tasa de recuperación de las luciérnagas</color>.",
  str_aircraft_desc_7103001 = "El <color=#00F6FF>MS en el Luminámetro</color> es fundamental cuando se explora el Territorio Secreto. El Sol Artificial aquí recarga el Luminámetro, <color=#00F6FF>proporcionando y restaurando MS</color>. Ciertos Aurorians son particularmente apasionados por la exploración y pueden acelerar aún más <color=#00F6FF>la tasa de recuperación de EM</color>.",
  str_aircraft_desc_7103002 = "El <color=#00F6FF>MS en el Luminámetro</color> es fundamental cuando se explora el Territorio Secreto. El Sol Artificial aquí recarga el Luminámetro, <color=#00F6FF>proporcionando y restaurando MS</color>. Ciertos Aurorians son particularmente apasionados por la exploración y pueden acelerar aún más <color=#00F6FF>la tasa de recuperación de EM</color>.",
