  str_aircraft_desc_7103004 = "El <color=#00F6FF>MS en el Luminámetro</color> es fundamental cuando se explora el Territorio Secreto. El Sol Artificial aquí recarga el Luminámetro, <color=#00F6FF>proporcionando y restaurando MS</color>. Ciertos Aurorians son particularmente apasionados por la exploración y pueden acelerar aún más <color=#00F6FF>la tasa de recuperación de EM</color>.",
  str_aircraft_desc_7103005 = "El <color=#00F6FF>MS en el Luminámetro</color> es fundamental cuando se explora el Territorio Secreto. El Sol Artificial aquí recarga el Luminámetro, <color=#00F6FF>proporcionando y restaurando MS</color>. Ciertos Aurorians son particularmente apasionados por la exploración y pueden acelerar aún más <color=#00F6FF>la tasa de recuperación de EM</color>.",
  str_aircraft_desc_7104001 = "Puede <color=#00F6FF>fabricar transportistas</color> aquí en intervalos de tiempo específicos, lo que reduce la cantidad de Prisma necesaria para despejar el escenario y otorga su rendimiento inmediatamente cuando usa Sweep. Ciertos Aurorianos incluso poseen Lumináticos que pueden <color=#00F6FF>aumentar la velocidad de fabricación de Carrier</color>.",
  str_aircraft_desc_7104002 = "Puede <color=#00F6FF>fabricar transportistas</color> aquí en intervalos de tiempo específicos, lo que reduce la cantidad de Prisma necesaria para despejar el escenario y otorga su rendimiento inmediatamente cuando usa Sweep. Ciertos Aurorianos incluso poseen Lumináticos que pueden <color=#00F6FF>aumentar la velocidad de fabricación de Carrier</color>.",
  str_aircraft_desc_7104003 = "Puede <color=#00F6FF>fabricar transportistas</color> aquí en intervalos de tiempo específicos, lo que reduce la cantidad de Prisma necesaria para despejar el escenario y otorga su rendimiento inmediatamente cuando usa Sweep. Ciertos Aurorianos incluso poseen Lumináticos que pueden <color=#00F6FF>aumentar la velocidad de fabricación de Carrier</color>.",
  str_aircraft_desc_7104004 = "Puede <color=#00F6FF>fabricar transportistas</color> aquí en intervalos de tiempo específicos, lo que reduce la cantidad de Prisma necesaria para despejar el escenario y otorga su rendimiento inmediatamente cuando usa Sweep. Ciertos Aurorianos incluso poseen Lumináticos que pueden <color=#00F6FF>aumentar la velocidad de fabricación de Carrier</color>.",
  str_aircraft_desc_7104005 = "Puede <color=#00F6FF>fabricar transportistas</color> aquí en intervalos de tiempo específicos, lo que reduce la cantidad de Prisma necesaria para despejar el escenario y otorga su rendimiento inmediatamente cuando usa Sweep. Ciertos Aurorianos incluso poseen Lumináticos que pueden <color=#00F6FF>aumentar la velocidad de fabricación de Carrier</color>.",
  str_aircraft_desc_7105001 = "El Pilar de prisma es donde <color=#00F6FF>Prisma se almacena</color>, y te permite usar Lumina para <color=#00F6FF>ganar Prisma</color>. Cuanto más alto sea el nivel de tu Pilar de Prisma, más rápido acumularás Prismas. Los Pilares de Prisma avanzados también pueden <color=#00F6FF>aumentar tu capacidad máxima de Prisma</color>. Ciertos Aurorians incluso poseen Luminatics que pueden <color=#00F6FF>mejorar tu tasa de adquisición Prisma</color>.",
  str_aircraft_desc_7105002 = "El Pilar de prisma es donde <color=#00F6FF>Prisma se almacena</color>, y te permite usar Lumina para <color=#00F6FF>ganar Prisma</color>. Cuanto más alto sea el nivel de tu Pilar de Prisma, más rápido acumularás Prismas. Los Pilares de Prisma avanzados también pueden <color=#00F6FF>aumentar tu capacidad máxima de Prisma</color>. Ciertos Aurorians incluso poseen Luminatics que pueden <color=#00F6FF>mejorar tu tasa de adquisición Prisma</color>.",
